'use strict';
const SurvivalEngine=(()=>{
 const clamp=n=>Math.max(0,Math.min(100,n));
 function create(party,seed=Date.now()>>>0){if(!Array.isArray(party)||party.length!==3||new Set(party).size!==3||party.some(id=>!survivalCast.some(p=>p.id===id)))throw Error('친구 3명을 골라주세요.');return {version:1,party:[...party],seed:seed>>>0,step:0,budget:120000,energy:75,fullness:35,mood:60,history:[],phase:'choose'};}
 function ending(s){if(s.energy<=0)return ['exhausted','체력 방전','즐거웠지만 다리가 먼저 퇴근했다. 다음 모임에는 쉬는 코스를 넣자.'];if(s.fullness<=0)return ['hungry','밥부터 먹을걸','배고픔이 모임을 이겼다. 총무의 다음 과제는 식사 시간 확보.'];if(s.step<7)return null;if(s.history.at(-1)?.choice==='oneMore')return ['taxi','막차는 떠났다','한 판만 더의 대가. 남은 공동 예산과 별개로 각자 택시비가 필요하다.'];if(s.mood>=90&&s.energy>=40)return ['perfect','다음 모임도 너가 총무','배도 채우고 분위기도 지켰다. 단톡방에 벌써 다음 약속이 올라온다.'];if(s.budget<10000)return ['broke','잔고까지 불태운 하루','통장은 가벼워졌지만 모임은 무사히 끝났다.'];return ['survived','전원 무사 귀환','약간의 우여곡절 끝에 오늘도 모임을 지켜냈다.'];}
 function choose(state,id){let s=JSON.parse(JSON.stringify(state));if(s.phase!=='choose'||ending(s))throw Error('선택할 차례가 아닙니다.');const scene=survivalScenes[s.step],c=scene.choices.find(c=>c.id===id);if(!c||c.cost>s.budget)throw Error('예산을 확인해주세요.');s.budget-=c.cost;for(const k of ['energy','fullness','mood'])s[k]=clamp(s[k]+c[k]);const affinity=Math.round(s.party.reduce((sum,id)=>sum+c.tags.reduce((v,t)=>v+(survivalCast[id].prefs[t]||0),0),0)/3);s.mood=clamp(s.mood+affinity);let event=null;if([2,4].includes(s.step)){const index=((s.seed%6)+(s.step===4?3:0))%6;event=survivalEvents[index];if(s.budget+(event.budget||0)>=0){s.budget+=event.budget||0;for(const k of ['energy','fullness','mood'])s[k]=clamp(s[k]+(event[k]||0));}else event=null;}s.history.push({scene:scene.id,choice:id,event:event?.id||null,affinity});s.step++;s.phase='reaction';return s;}
 function next(s){s=JSON.parse(JSON.stringify(s));if(s.phase!=='reaction')throw Error('대화를 먼저 확인해주세요.');s.phase=ending(s)?'end':'choose';return s;}
 function restore(value){try{if(value?.version!==1||!Number.isInteger(value.seed)||!Array.isArray(value.history)||value.history.length>7)return null;let s=create(value.party,value.seed);for(const h of value.history){s=choose(s,h.choice);s=next(s);}if(value.phase==='reaction'&&s.history.length)s.phase='reaction';return s;}catch{return null;}}
 return {create,choose,next,ending,restore};
})();
